{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "རྗེ་སྐལ་ལྡན་རྒྱ་མཚོའི་ཞལ་ནས།",
      "head": "སྤྲང་བདག་ལ་བློ་གཏད་སློབ་མ་རྣམས། །",
      "tail": "བཀའ་དྲི་མེད་དགོངས་དོན་འཚོལ་ལ་འབོད། །"
    },
    {
      "label": "QUOTE",
      "frame": "གྲུབ་ཆེན་ཏཱ་ར་ན་ཐཱའི་ཞལ་ནས།",
      "head": "ཆོས་ཐམས་ཅད་གཅིག་དུ་བྲལ་དང་རྟེན་འབྱུང་གི་རིགས་པ་",
      "tail": "ཚུལ་ལ་དམིགས་ནས་གསལ་སྟོང་དུ་བསྒོམ་མོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "པོ་ཏོ་པའི་གསུང་སྒྲོས་བེའུ་བུམ་སྔོན་པོ་ལས། ཏིང་ངེ་འཛིན་གྱི་རྒྱལ་པོ་ལས།",
      "head": "ཆོས་ཐམས་ཅད་མཉམ་པ་ཉིད་དུ་རྣམ་པར་སྤྲོས་",
      "tail": "དེ་གཅིག་པུས་ཆོག་ཟེར་"
    },
    {
      "label": "QUOTE",
      "frame": "པོ་ཏོ་བའི་ཞལ་ནས།",
      "head": "དེ་འདིར་ཁྱོགས་དང་གསུངས་ནས་གཟིགས་ཏེ།",
      "tail": "སྤྱོད་པ་བ་ནག་པོའི་གཏམ་རྒྱུད་དང་འདྲ་བ་ཡིན་"
    },
    {
      "label": "QUOTE",
      "frame": "མི་ལའི་ཞལ་ནས།",
      "head": "ཡང་དག་པར་རྫོགས་པའི་སངས་རྒྱས་ཀྱི་",
      "tail": "ལོ་པཎ་སྤྲུལ་སྐུ་རྣམས་ཀྱིས་ཁྱེར་ག་ན་འོང་"
    },
    {
      "label": "QUOTE",
      "frame": "བརྒྱད་སྟོང་པ་ལས།",
      "head": "ཆོས་ཐམས་ཅད་ཀྱི་མི་དམིགས་པ་གང་ཡིན་པ་དེ་",
      "tail": "ཤེས་རབ་ཀྱི་ཕ་རོལ་ཏུ་ཕྱིན་པའོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྟོང་ཕྲག་བརྒྱ་བ་ལས་ཀྱང་།",
      "head": "གཟུགས་ཡིད་ལ་མི་བྱེད། ཚོར་བ་ཡིད་ལ་མི་བྱེད།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དམ་པ་རྒྱ་གར་ལ།",
      "head": "རྫོགས་པ་ཆེན་པོ་ལ་ལས་དཀར་ནག་གི་འབྲས་བུ་མེད་སྐད་པ་དེ་བདེན་ནམ་ཞུས་པས། རྫོགས་ན་བདེན་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཆོས་རྗེའི་ཞལ་ནས།",
      "head": "རྟོགས་ལྡན་ཉམས་མྱོང་བདེ་གཤེགས་བཀའ་དང་འདྲ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དེ་སྐད་དུ་ཡང་།",
      "head": "ལྷ་ཡི་སྐད་དང་ཀླུ་དང་གནོད་སྦྱིན་སྐད། །",
      "tail": "ཐམས་ཅད་སྐད་དུ་བདག་གིས་ཆོས་སྟོན་ཏོ། །"
    },
    {
      "label": "QUOTE",
      "head": "གང་ལ་སེམས་ཀྱི་དམ་པ་རིན་ཆེན་དེ། །",
      "tail": "བདེ་བའི་འབྱུང་གནས་དེ་ལ་ཕྱག་འཚལ་ལོ། །"
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་རིན་པོ་ཆེས་སྒྲོན་གསལ་ལས།",
      "head": "རྡོ་རྗེའི་ཚིག་རེ་ལ་བཤད་པ་མི་འདྲ་བ་མང་པོ་འཇུག་པའི་ཕྱིར་ཏེ། དཔེར་ན་ལེའུ་བདུན་པར། དེ་བཞིན་གཤེགས་པའི་ཚོགས་བསད་ན། དངོས་གྲུབ་མཆོག་ཐོབ་པར་གསུངས་པ། མགོན་པོ་ཀླུ་སྒྲུབ་ཀྱིས་ལྷག་མོས་འོད་གསལ་སྡུད་པ་ལ་སྦྱར། འཕགས་པ་ལྷས་དེའི་དོན་རྫོགས་རིམ་གྱི་འོད་གསལ་དུ་འཇུག་པ་ལ་བཤད།",
      "tail": ""
    }
  ]
}
